// Lookup table of all maneuver bitmaps
static const NavManeuverBitmap s_navBitmaps[] = {
  { "straight", 146, 32, 75, 264, s_bm_straight_alpha, nullptr },
  { "turn-right", 108, 38, 144, 265, s_bm_turn_right_alpha, nullptr },
  { "turn-left", 108, 37, 143, 266, s_bm_turn_left_alpha, nullptr },
  { "slight-right", 108, 60, 143, 243, s_bm_slight_right_alpha, nullptr },
  { "slight-left", 108, 60, 144, 243, s_bm_slight_left_alpha, nullptr },
  { "sharp-right", 108, 68, 147, 235, s_bm_sharp_right_alpha, nullptr },
  { "sharp-left", 108, 68, 146, 235, s_bm_sharp_left_alpha, nullptr },
  { "uturn", 108, 47, 141, 256, s_bm_uturn_alpha, nullptr },
  { "merge", 107, 44, 138, 259, s_bm_merge_alpha, nullptr },
  { "roundabout", 108, 106, 172, 197, s_bm_roundabout_alpha, nullptr },
  { "arrive", 138, 69, 92, 226, nullptr, s_bm_arrive_rgb565 },
};

const NavManeuverBitmap* getNavManeuverBitmap(const String &m) {
  if (m == "turn-right" || m == "right") {
    return &s_navBitmaps[1];
  } else if (m == "turn-left" || m == "left") {
    return &s_navBitmaps[2];
  } else if (m == "slight-right" || m == "keep-right") {
    return &s_navBitmaps[3];
  } else if (m == "slight-left" || m == "keep-left") {
    return &s_navBitmaps[4];
  } else if (m == "sharp-right") {
    return &s_navBitmaps[5];
  } else if (m == "sharp-left") {
    return &s_navBitmaps[6];
  } else if (m == "uturn" || m == "u-turn") {
    return &s_navBitmaps[7];
  } else if (m == "merge" || m == "highway-merge") {
    return &s_navBitmaps[8];
  } else if (m == "roundabout") {
    return &s_navBitmaps[9];
  } else if (m == "arrive") {
    return &s_navBitmaps[10];
  }
  return &s_navBitmaps[0];
}
